pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: give some ether to the contract and a user
        vm.deal(address(c), 10 ether);
        address user = address(0x1234);
        vm.deal(user, 1 ether);

        // User sends 1 ether to addToBalance
        vm.prank(user);
        c.addToBalance{value: 1 ether}();

        // Now user tries to withdrawBalance (single call, no reentrancy)
        // Reference: should succeed and transfer ether; buggy: also succeeds (but reentrancy not tested here)
        // Instead, we test that the buggy contract allows a reentrant call that the reference prevents.
        // Reset: deploy fresh contract for clear test
        c = new C();
        vm.deal(address(c), 10 ether);
        vm.deal(user, 1 ether);

        // User deposits 1 ether
        vm.prank(user);
        c.addToBalance{value: 1 ether}();

        // User attempts reentrant withdraw via a malicious contract
        // (We simulate by calling withdrawBalance twice in same tx via a contract that reenters)
        // For simplicity, we use a direct second call (since buggy lacks lock)
        // But the test just checks different final state:
        // Reference: after withdrawBalance, balance reset to 0. Buggy: if reentrant, could drain more.
        // However the given difference says: after addToBalance(), value differs.
        // Actually, the mutant deletes locked_=true, so reentrancy possible in withdrawBalance.
        // The concrete scenario: call addToBalance, then call withdrawBalance twice in one tx.
        // Reference: first withdraw succeeds, second reverts due to reentrancy lock.
        // Buggy: both succeed, draining more ether.

        // Let's test directly: deploy, user deposits 1 ether, then call withdrawBalance twice.
        // Since we can't reenter in same tx easily without a helper, we rely on the fact that
        // after the first withdrawBalance, the buggy contract does not re-lock, but the reference does.
        // Actually the buggy modifier has no locked_=true, so it never prevents reentrancy.
        // So we can call withdrawBalance twice from same user in separate txs: reference allows only one successful withdrawal (since second reverts because locked_ is true after first), buggy allows both.

        // Reset again
        c = new C();
        vm.deal(address(c), 10 ether);
        vm.deal(user, 1 ether);

        vm.prank(user);
        c.addToBalance{value: 1 ether}();

        // First withdraw (reference: ok, buggy: ok)
        vm.prank(user);
        c.withdrawBalance();

        // Second withdraw (reference: should revert because locked_ is true, buggy: should succeed because no lock)
        bool secondOk;
        vm.prank(user);
        try c.withdrawBalance() {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // Reference: second withdraw should revert (secondOk == false)
        // Buggy: second withdraw should succeed (secondOk == true)
        // So assert that secondOk is false (reference holds, bug breaks)
        assertTrue(!secondOk);
    }
}

