pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        vm.deal(attacker, 2 wei);

        // First call to addToBalance() sends 1 wei
        vm.prank(attacker);
        c.addToBalance{value: 1 wei}();

        // In the buggy contract, locked_ is still false after the first call,
        // so the attacker can re-enter addToBalance() via the fallback while withdrawBalance() is being executed.
        // We simulate a second direct call to addToBalance() to check if reentrancy is possible.
        vm.prank(attacker);
        c.addToBalance{value: 1 wei}();

        // The reference contract: locked_ was true during the first call (nonReentrant_ sets it true),
        // so the second call reverts. The buggy contract: locked_ was never set true, so the second call succeeds,
        // doubling the balance to 2 wei. We assert that the balance is 1 wei (reference behavior).
        assertTrue(c.getBalance(attacker) == 1 wei, "Balance should be 1 wei if reentrancy is prevented");
    }
}

