pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: give user1 some ether
        address user1 = address(0x1234);
        vm.deal(user1, 5 ether);

        // User1 calls addToBalance() with 1 wei
        vm.prank(user1);
        c.addToBalance{value: 1 wei}();

        // Now user1's balance should be 1 wei
        assertEq(c.getBalance(user1), 1 wei);

        // Simulate a reentrant call: user1 calls withdrawBalance(), which should revert if reentrancy is prevented
        // We'll try to make a reentrant call by having the contract call back into addToBalance() during withdrawal
        // To do this, user1 must be a contract that reenters on receive()
        // Deploy a simple attacker contract
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), 1 wei);

        // Fund the contract so there's ether to withdraw
        vm.deal(address(c), 1 ether);

        // Attacker adds 1 wei to its balance
        vm.prank(address(attacker));
        attacker.addToBalance{value: 1 wei}();

        // Now attacker calls withdrawBalance, which will reenter in its receive() function
        // This should revert in the reference contract but succeed in the buggy one
        vm.prank(address(attacker));
        bool ok = address(attacker).call(abi.encodeWithSignature("withdrawAndReenter()"));

        // The reference contract should revert (ok = false), buggy contract should succeed (ok = true)
        // We assert that the reference holds: revert happens
        assertTrue(!ok);
    }
}

contract Attacker {
    C public c;
    bool public reentered = false;

    constructor(address _c) {
        c = C(_c);
    }

    function addToBalance() external payable {
        c.addToBalance{value: msg.value}();
    }

    function withdrawAndReenter() external {
        c.withdrawBalance();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.addToBalance(); // reenter with zero value
        }
    }
}

