pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious contract to perform reentrancy
        address attacker = address(new ReentrancyAttacker(c));

        // Fund the attacker contract with 1 wei via addToBalance
        vm.deal(attacker, 1 wei);
        vm.prank(attacker);
        c.addToBalance{value: 1 wei}();

        // Now call withdrawBalance on the attacker contract, which will reenter
        vm.prank(attacker);
        (bool success, ) = attacker.call(abi.encodeWithSignature("withdrawAndReenter()"));

        // In the reference contract, the reentrant call should fail and balance remains 1
        // In the buggy contract, the reentrant call succeeds and balance becomes 0
        uint256 balance = c.getBalance(attacker);
        assertTrue(balance == 1 wei, "Balance should be 1 wei if reentrancy prevented");
    }
}

contract ReentrancyAttacker {
    C public target;
    constructor(C _target) {
        target = _target;
    }

    function withdrawAndReenter() public {
        target.withdrawBalance();
    }

    receive() external payable {
        if (address(target).balance >= 1 wei) {
            target.withdrawBalance();
        }
    }
}

