pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1234);

    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // Deploy a contract that reverts when receiving ether
        Rejector rejector = new Rejector();

        // Fund Alice
        vm.deal(alice, 1 ether);

        // Alice deposits 1 ether
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Now Alice tries to withdraw; we redirect the call to the rejector contract
        // by changing the caller's address to the rejector? No, we cannot change msg.sender arbitrarily.
        // Instead, we have Alice withdraw and the call is to msg.sender which is Alice (a normal EOA), so it will succeed.
        // To cause failure, we need the recipient to reject: we can have Alice withdraw but first transfer her address to the rejector by selfdestruct? Not possible.
        // Alternative: Use a contract as user that rejects ether. So we set up Bob as a contract that reverts on receive.
        // Let Bob be address(rejector). But rejector is a contract, we need to make it the user.
        // We'll rename: use Bob contract as the user.
        // Actually simpler: create a contract that acts as user and rejects incoming ether.
        // Then the deposit comes from that contract (prank as contract).
        // Let's do: deploy UserContract that can call addToBalance and withdrawBalance.
        // It will reject any incoming ether via receive().
        // Then after deposit, when it calls withdrawBalance, the external call fails.

        // Better approach: just test with a normal EOA Alice; the call always succeeds.
        // No revert difference. So need a different way: use a contract that rejects.
        // Let's restructure: deploy a UserContract that can call addToBalance and withdrawBalance.
        // In withdrawBalance, the contract calls msg.sender.call, which is the UserContract itself, and it rejects.
        // The UserContract implements receive() to revert.
        // Then reference will revert (call fails), buggy will succeed.

        UserContract user = new UserContract(c);

        // Fund user contract
        vm.deal(address(user), 1 ether);

        // User deposits 1 ether
        user.deposit{value: 1 ether}();

        // User tries to withdraw
        // For reference: it will revert. For buggy: it will succeed.
        // But we need to check the revert boolean of the call to withdrawBalance.
        // We call c.withdrawBalance() on behalf of user.

        bool referenceReverted = false;
        try c.withdrawBalance() { referenceReverted = false; } catch { referenceReverted = true; }
        // The reference C (original) will revert because the external call to user fails.
        // The buggy M will not revert because balance set to 0 first and then send 0 which doesn't trigger receive?
        // Actually sending 0 ether still triggers receive() if recipient is a contract.
        // So it would still revert. Need to ensure buggy does not revert: if balance already 0, it sends 0 to user contract, which reverts as well.
        // Hmm.
        // Let's think: In buggy, userBalance[user] is set to 0, then call.value(0). The user's receive reverts on any call. So it reverts too.
        // So no difference.
        // Need a scenario where the external call succeeds in buggy but fails in reference.
        // For reference: it sends the full balance (e.g., 1 ether) to a contract that rejects large amounts but accepts 0? That's weird.
        // Simpler: use a contract that accepts ether but reverts on larger than 0? Not realistic.
        // Actually we can use a contract that has a receive that reverts if msg.value > 0. Then reference sends 1 ether -> revert; buggy sends 0 ether -> success.
        // That works!
    }
}

contract Rejector {
    receive() external payable {
        if (msg.value > 0) {
            revert("No ether");
        }
    }
}

contract UserContract {
    C c;
    constructor(C _c) { c = _c; }
    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }
    function withdraw() external {
        c.withdrawBalance();
    }
    receive() external payable {
        if (msg.value > 0) {
            revert("No ether");
        }
    }
}

