pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a receiver contract that always reverts on receive
        address receiver = address(new Rejector());

        // Give receiver some ether to be able to use it as msg.sender
        vm.deal(receiver, 1 ether);

        // Prank as receiver, deposit 1 ether into C
        vm.prank(receiver);
        c.addToBalance{value: 1 ether}();

        // Now prank as receiver and call withdrawBalance
        vm.prank(receiver);

        // Use try/catch to observe revert behavior
        bool success;
        try c.withdrawBalance() {
            success = true;
        } catch {
            success = false;
        }

        // The reference reverts (success=false), the buggy succeeds (success=true)
        // Assert false to catch the bug: if the test passes (assertTrue(false) would revert),
        // it means the buggy version succeeded where it should have reverted.
        // Actually we want: reference succeeds (success == false for reference, true for bug)
        // For simplicity: on the reference, success should be false; on the bug, true.
        // Since we are testing against a given C, we assert the expected reference behavior:
        // success must be false.
        assertTrue(!success, "Reference should revert");
    }
}

contract Rejector {
    receive() external payable {
        revert("rejecting ether");
    }
    function getBalance(address) external view returns (uint) {
        return 0;
    }
}

