pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1111);
    address bob = address(0x2222);

    function setUp() public { 
        c = new C(); 
    }

    function testRegression_property() public {
        // Bob sends 1 ether to the contract (not through addToBalance, so it goes to contract balance but not to any user's balance)
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "bob deposit failed");

        // Alice deposits 1 ether via addToBalance
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Alice calls withdrawBalance: reference sends 1 ether to Alice, then sets balance to 0; buggy sets balance to 0, then sends 0 ether.
        vm.prank(alice);
        c.withdrawBalance();

        // Now Alice calls withdrawBalance again: reference: userBalance[alice] is 0, so sends 0 ether and reverts because call succeeds but sends 0 value; but actually `call{value:0}` succeeds for EOA, so no revert. Buggy: userBalance[alice] already 0, sets to 0, sends 0 ether.
        // However the second withdrawal does not change contract balance significantly. The key is the contract balance after both actions:
        // Reference: Bob's 1 ether is still in the contract (since Bob didn't call addToBalance, his ether is not tracked). Alice's 1 ether was withdrawn -> 0. Reference contract balance = 1 ether.
        // Buggy: Alice's first withdrawal sent 0 ether (since balance zeroed before call), so Alice's 1 ether remains in contract balance (since no send), plus Bob's 1 ether = 2 ether? Wait, we need to recalc.
        // Actually in reference: Alice deposits 1 ether -> userBalance[alice]=1, contractBalance=alice's 1 + bob's 1 = 2 ether. withdrawBalance sends 1 ether to alice, contractBalance=1 ether (bob's). Buggy: before send, userBalance[alice]=1 -> set to 0, then call sends 0 ether -> alice gets 0, contractBalance remains 2 ether. So reference contract balance = 1 ether, buggy = 2 ether? Let's trace: initial contract balance = 0. Bob sends 1 ether -> balance=1. Alice sends 1 ether via addToBalance -> balance=2. Withdraw: reference sends 1 -> balance=1. Buggy: sets balance to 0, sends 0 -> balance=2. Then second withdraw: both read userBalance[alice]=0, send 0 -> balance unchanged. So reference=1, buggy=2. That's a difference.
        // But to match the problem statement that the reference breaks on a revert? It's fine, we just need a concrete observable difference. Let's simplify with a single withdraw that fails on a contract that rejects, but that was 'already tried'. So let's stick with the above two-account scenario.
        // Actually the above yields contract balance difference. Let's measure that.
        if (address(c).balance == 1 ether) {
            assertTrue(true); // reference passes
        } else {
            assertTrue(address(c).balance == 2 ether); // buggy fails because it has 2 ether
        }
        // But the assertion must be a single statement that holds for reference and fails for buggy.
        // So: assertTrue(address(c).balance == 1 ether);
        // If buggy has 2 ether, this fails.
        assertTrue(address(c).balance == 1 ether);
    }
}

