pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = makeAddr("alice");
        vm.deal(alice, 1 ether);

        // Deploy a receiver contract that always reverts on receive
        Reverter reverter = new Reverter();

        // Alice deposits 1 ether
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Alice calls withdrawBalance, but the receiver is the reverter
        // The reference should revert (because the call fails), so we use try/catch
        vm.prank(alice);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));
        // After the call:
        // Reference: reverted -> balance unchanged (1 ether), contract balance = 1 ether
        // Buggy: did not revert -> balance set to 0, contract balance = 0 ether
        // We observe via getBalance (public getter) and address(c).balance
        bool refPassed = (c.getBalance(alice) == 1 ether && address(c).balance == 1 ether);
        bool bugPassed = (c.getBalance(alice) == 0 && address(c).balance == 0);
        // Exactly one assertion: the reference holds this, the buggy breaks it
        assertTrue(refPassed && !bugPassed);
    }
}

contract Reverter {
    receive() external payable { revert(); }
}
